// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), 0);
        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;

        vm.prank(address(attacker));
        attacker.attack();

        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter >= balanceBefore - depositAmount);
    }
}

contract ReentrantAttacker {
    ReentrancyDAO public target;
    bool private attacking;
    constructor(ReentrancyDAO _target) { target = _target; }
    function attack() external payable {
        attacking = true;
        target.withdrawAll();
        attacking = false;
    }
    receive() external payable {
        if (attacking) {
            target.withdrawAll();
        }
    }
}
